set -euo pipefail; python3 -c 'exec('"'"'from pathlib import Path\nimport copy,json\nroot=Path.cwd()\nproof=Path(\'"'"'/tmp/cx-m10-cloud-step\'"'"')\n(proof/\'"'"'driver/src\'"'"').mkdir(parents=True)\n(proof/\'"'"'inputs\'"'"').mkdir()\n(proof/\'"'"'results\'"'"').mkdir()\nmanifest=\'"'"'[package]\\nname="m10-certified-step-proof"\\nversion="0.0.0"\\nedition="2024"\\n[dependencies]\\n\'"'"'\nfor name in [\'"'"'catallax-numbers\'"'"',\'"'"'catallax-recipe\'"'"',\'"'"'catallax-features\'"'"',\'"'"'catallax-step\'"'"',\'"'"'catallax-topology\'"'"']:\n    manifest+=f\'"'"'{name} = {{ path = "{root}/crates/{name}" }}\\n\'"'"'\nmanifest+=\'"'"'serde_json = "1"\\n\'"'"'\n(proof/\'"'"'driver/Cargo.toml\'"'"').write_text(manifest)\n(proof/\'"'"'driver/src/main.rs\'"'"').write_text(\'"'"'use catallax_numbers::{Decider, Rational, with_operation_budget};\\nuse catallax_recipe::Recipe;\\nuse catallax_step::{Seams, StepOptions, write_step};\\nuse serde_json::json;\\nuse std::{env, fs, num::NonZeroUsize, path::PathBuf};\\n\\nfn main() {\\n    let args: Vec<_> = env::args().skip(1).collect();\\n    let input = PathBuf::from(&args[0]);\\n    let out = PathBuf::from(&args[1]);\\n    let requested = args.get(2).map(String::as_str).unwrap_or("1");\\n    let count = if requested == "all" {\\n        std::thread::available_parallelism().unwrap().get()\\n    } else {\\n        requested.parse().unwrap()\\n    };\\n    catallax_numbers::set_threads(Some(NonZeroUsize::new(count).unwrap()));\\n    let threads = catallax_numbers::threads();\\n    let recipe: Recipe = serde_json::from_slice(&fs::read(&input).unwrap()).unwrap();\\n    let tolerance = Rational::parse("1e-7").unwrap();\\n    let (result, work) = with_operation_budget(20_000_000, || {\\n        let mut dec = Decider::default();\\n        let built = catallax_features::evaluate(&recipe, &mut dec)\\n            .map_err(|error| ("refused", format!("build: {error:?}")))?;\\n        let body = built.model.body(built.result);\\n      